entries[387619] = { ["name"] = "Infusion", ["text"] = "100 Meter Reichweite\nSofort\nDie Einflößerin der Primalisten kanalisiert auf den urtümlichen Tsunami und erhöht dessen verursachten Schaden um 1%. Dieser Effekt stapelt sich alle 5 Sek. weiter, bis er unterbrochen wird." }
