entries[387621] = { ["name"] = "Drachenfeuergebräu", ["text"] = "Sofort\nNach dem Einsatz von 'Feuerodem' spuckt Ihr weitere 2-mal Feuer und verursacht jedes Mal (20% der Angriffskraft) Feuerschaden.\n\nDer Schaden von 'Feuerodem' wird um bis zu 100% erhöht, basierend auf der Höhe des aktuell gestaffelten Schadens." }
entries[387622] = { ["name"] = "Urzeitlicher Sog", ["text"] = "Sofort\nBeim Einsatz von 'Urzeitliche Welle' wird sofort und 12 Sek. lang alle 3 Sek. 'Lavasog' ausgelöst. Wird ein 'Lavasog' durch 'Urzeitliche Welle' ausgelöst, erhöht er den Schaden Eurer nächsten 'Lavaeruption' um 15%." }
entries[387623] = { ["name"] = "Blitzverheerung", ["text"] = "300 Meter Reichweite\nSofort\nRaszageth fegt über die Plattform und atmet dabei Blitze in einer Linie aus. Fügt Spielercharakteren im Einschlagsbereich 1766570 Naturschaden zu." }
entries[387624] = { ["name"] = "Erschütternde Hiebe", ["text"] = "Sofort\nVerringert den gestaffelten Schaden um (Angriffskraft * 90 / 100)." }
entries[387625] = { ["name"] = "Erschütternde Hiebe", ["text"] = "Beim Einsatz von 'Blackout-Tritt' wird Euer gestaffelter Schaden um (Angriffskraft * 90 / 100) verringert." }
entries[387626] = { ["name"] = "Seelenbrand", ["text"] = "Sofort\nVerbraucht einen Seelensplitter, um die verborgene Macht Eurer Zauber zu erschließen.\n\nDämonischer Zirkel: Teleportieren : Erhöht Eure Bewegungsgeschwindigkeit um 50% und lässt Euch für 6 Sek. immun gegen bewegungseinschränkende und Bewegungsunfähigkeitseffekte werden.\n\nDämonisches Tor : Wird zu einem Spontanzauber.\n\nBlutsauger : Gewährt für 30 Sek. einen Absorptionsschild in Höhe der hervorgerufenen Heilung. Der Absorptionswert kann 30% Eurer maximalen Gesundheit nicht überschreiten.\n\nLebenslinie : Stellt 140% mehr Gesundheit wieder her und verringert den von Eurem Diener erlittenen Schaden 10 Sek. lang um 30%.\n\nGesundheitsstein : Erhöht die Heilung Eures Gesundheitssteins um 30%. Zusätzlich wird Eure maximale Gesundheit für 12 Sek. um 20% erhöht." }
entries[387627] = { ["name"] = "Gegenwind", ["text"] = "300 Meter Reichweite\nSofort\nBeim Tod explodiert der instabile Infusor gewaltsam, fügt allen Spielercharakteren 88380 Naturschaden zu und stößt sie zurück." }
entries[387629] = { ["name"] = "Fauliger Wind", ["text"] = "25 Meter Reichweite\nWirken in 3 sek.\nFügt Gegnern vor dem Zaubernden 6061123 Schattenschaden zu und verringert die erhaltene Heilung getroffener Spielercharaktere 10 Sek. lang um 20%." }
entries[387630] = { ["name"] = "Seelenbrand: Blutsauger", ["text"] = "Sofort\nVerbraucht einen Seelensplitter, um die verborgene Macht Eurer Zauber zu erschließen.\n\nDämonischer Zirkel: Teleportieren : Erhöht Eure Bewegungsgeschwindigkeit um 50% und lässt Euch für 6 Sek. immun gegen bewegungseinschränkende und Bewegungsunfähigkeitseffekte werden.\n\nDämonisches Tor : Wird zu einem Spontanzauber.\n\nBlutsauger : Gewährt für 30 Sek. einen Absorptionsschild in Höhe der hervorgerufenen Heilung. Der Absorptionswert kann 30% Eurer maximalen Gesundheit nicht überschreiten.\n\nLebenslinie : Stellt 140% mehr Gesundheit wieder her und verringert den von Eurem Diener erlittenen Schaden 10 Sek. lang um 30%.\n\nGesundheitsstein : Erhöht die Heilung Eures Gesundheitssteins um 30%. Zusätzlich wird Eure maximale Gesundheit für 12 Sek. um 20% erhöht." }
entries[387631] = { ["name"] = "Ehrfurcht erwecken", ["text"] = "100 Energie 100 Meter Reichweite\nWirken in 3 sek.\nErweckt überwältigende Ehrfurcht in bis zu 3 Gegnern, betört sie und erhöht ihren verursachten Schaden 15 Sek. lang um 100%. Betörte Ziele werden befreit, wenn ihre Gesundheit unter 30% fällt." }
