entries[388100] = { ["name"] = "Zerstörerischer Wind", ["text"] = "100 Meter Reichweite\nWirken in 2.5 sek.\nBei 100 Energie feuert Teera verheerende Windgeschosse auf anvisierte Spielercharaktere und fügt ihnen dadurch 5576234 Naturschaden zu.\n\n4 Tornados entfernen sich vom Einschlagsort, fügen getroffenen Spielercharakteren 3636674 Naturschaden zu und stoßen sie zurück." }
