entries[388104] = { ["name"] = "Ritual der Entweihung", ["text"] = "100 Meter Reichweite\nSofort\nFügt dem gegnerischen Ziel 30 Schattenschaden zu." }
entries[388106] = { ["name"] = "Seelennarbe", ["text"] = "'Gleve werfen' fügt Zielen in Verlauf von 6 Sek. zusätzlich 80% des verursachten Schadens als Chaosschaden zu." }
entries[388107] = { ["name"] = "Wütende Flammen", ["text"] = "Jedes Mal, wenn 'Feuerbrandaura' Schaden verursacht, sammeln sich 30% des von bis zu 3 kritischen Treffern verursachten Schadens als 'Wütende Flammen' an.\n\nWenn 'Feuerbrandaura' abläuft, explodiert Ihr und fügt Gegnern in der Nähe den gesammelten Schaden von 'Wütende Flammen' zu." }
entries[388108] = { ["name"] = "Initiative", ["text"] = "Wenn Ihr einem Gegner Schaden zufügt, bevor er Euch Schaden zufügt, wird Eure kritische Trefferchance 5 Sek. lang um 10% erhöht.\n\n'Rachsüchtiger Rückzug' setzt die Möglichkeit zurück, diesen Effekt bei Gegnern auszulösen, mit denen Ihr im Kampf verwickelt seid." }
entries[388109] = { ["name"] = "Teufelsfeuerherz", ["text"] = "Erhöht die Effektdauer von 'Feuerbrandaura' und 'Zeichen der Flamme' um 2 Sek." }
entries[388110] = { ["name"] = "Elende Niederlage", ["text"] = "100 Meter Reichweite\nWenn der Effekt von 'Zeichen des Elends' bei Gegnern abläuft, fügt Ihr ihnen 5 Sek. lang 20% mehr Schaden zu." }
entries[388111] = { ["name"] = "Dämonenmaulkorb", ["text"] = "Nachdem sie von einem Eurer Zeichen betroffen wurden, fügen Gegner Euch 8 Sek. lang um 8% verringerten Magieschaden zu." }
entries[388112] = { ["name"] = "Chaotische Verwandlung", ["text"] = "Wenn Ihr 'Metamorphose' aktiviert, werden die Abklingzeiten von 'Klingentanz' und 'Augenstrahl' sofort abgeschlossen." }
entries[388113] = { ["name"] = "Isolierte Beute", ["text"] = "'Chaosnova', 'Augenstrahl' und 'Feuerbrandaura' gewähren Boni, wenn 1 Ziel getroffen wird.\n\nChaosnova :\nBetäubungsdauer wird um 2 Sek. erhöht.\n\nAugenstrahl :\nVerursacht 30% mehr Schaden.\n\nFeuerbrandaura :\nErzielt immer kritische Treffer." }
entries[388114] = { ["name"] = "Mit allen Mitteln", ["text"] = "'Meisterschaft: Dämonische Präsenz' sorgt zusätzlich dafür, dass Euer verursachter Arkan-, Feuer-, Frost-, Natur- und Schattenschaden zu Chaosschaden wird, und erhöht diesen Schaden um 11.2%." }
entries[388115] = { ["name"] = "Blitzverheerung", ["text"] = "Unbegrenzte Reichweite\nSofort\nRaszageth fegt über die Plattform und atmet dabei Blitze in einer Linie aus. Fügt Spielercharakteren im Einschlagsbereich 1766570 Naturschaden zu." }
