entries[388193] = { ["name"] = "Jadefeuerstampfen", ["text"] = "4% von Grundmana 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\n1 Aufladung\nWindläufer\nSchlägt heftig auf den Boden, um für 30 Sek. einen Jadeweg freizulegen, der Eure Bewegungsgeschwindigkeit innerhalb des Effektbereichs um 20% erhöht. Fügt bis zu 5 vom Jadeweg erfassten Gegnern innerhalb von 30 Metern (40% der Angriffskraft) Naturschaden zu und heilt bis zu 5 Verbündete in diesem Bereich um (91% der Zaubermacht) Gesundheit. Bis zu 5 vom Weg erfasste Gegner\n\nNebelwirker\nSchlägt heftig auf den Boden, um für 30 Sek. einen Jadeweg freizulegen. Fügt bis zu 5 vom Jadeweg erfassten Gegnern innerhalb von 30 Metern (40% der Angriffskraft) Naturschaden zu und heilt bis zu 5 Verbündete in diesem Bereich um (91% der Zaubermacht) Gesundheit.\n\nWährend Ihr innerhalb des Wegs kämpft, haben Eure Fähigkeiten eine Chance von 6%, die Abklingzeit von 'Jadefeuerstampfen' abzuschließen.\n\n(500ms Abklingzeit)" }
