entries[388694] = { ["name"] = "Murlocstampede", ["text"] = "40 Meter ReichweiteKanalisiert (Wirken in 10 sek.) 3 min Abklingzeit\nRuft eine Tierherde aus der Wildnis herbei, die um Euch herumstürmt und Euren Gegnern im Laufe von 7 Sek. [(300% der Angriffskraft) * 3] körperlichen Schaden zufügt." }
