entries[388696] = { ["name"] = "Frostatem", ["text"] = "15 Meter Reichweite\nWirken in 3 sek.\nStuns all enemies in front of the caster, rendering them unable to move or attack for 3 Sek..\nInflicts 30 Frost damage to all enemies in front of the caster." }
entries[388698] = { ["name"] = "Rasendes Wegputzen", ["text"] = "20 Meter Reichweite\nWirken in 2.5 sek.\nKneifi rast durch sein Ziel, fügt ihm 20 körperlichen Schaden zu und betäubt Spielercharaktere, die von dem Ansturm getroffen werden, für 2 Sek. Sek." }
entries[388699] = { ["name"] = "Eruption", ["text"] = "Sofort\nGranyth erzeugt im Erdreich unter sich eine Eruption, die allen Spielercharakteren alle 3 Sek. 35 Naturschaden zufügt. Jedes Mal, wenn dies geschieht, wird der Schaden nachfolgender Schockwellen erhöht." }
