entries[388810] = { ["name"] = "Tolle Rolle", ["text"] = "Sofort\nWährend [ Chitorpedo : 'Chitorpedo' / 'Rollen'] seid Ihr immun gegen bewegungseinschränkende und Bewegungsunfähigkeitseffekte." }
