entries[388812] = { ["name"] = "Lebhafte Belebung", ["text"] = "Nebelwirker\nNach dem Einsatz von 'Tritt der aufgehenden Sonne' wird Euer nächster Einsatz von 'Beleben' ein Spontanzauber und seine Heilung um 20% erhöht.\n\nBraumeister, Windläufer\nNach dem Einsatz von 'Tritt der aufgehenden Sonne' wird Euer nächster Einsatz von 'Beleben' ein Spontanzauber und seine Heilung um 20% erhöht.\n\nDieser Effekt verringert zusätzlich die Energiekosten von 'Beleben' um 75%.\n\n(500ms Abklingzeit)" }
