entries[388815] = { ["name"] = "Elektrifizierte Kiefer", ["text"] = "Unbegrenzte Reichweite\nSofort\nRaszageth schnappt mit elektrifizierten Kiefern nach ihrem aktuellen Ziel und fügt ihm 706741 körperlichen Schaden sowie 353314 Naturschaden zu. Dabei verwundet sie das Ziel, wodurch es alle 1 Sek. 52997 Naturschaden erleidet. Die Wunde erhöht außerdem den erlittenen körperlichen Schaden des Ziels 33 Sek. lang um 100%." }
