entries[388818] = { ["name"] = "Arkane Vergrößerung", ["text"] = "Animabonus\n100 Meter Reichweite\nSofort\nLässt Euch größer werden, erhöht den verursachten Schaden um 15% und verringert den erlittenen Schaden sowie die Bewegungsgeschwindigkeit um diesen Wert. Hält 5 Min. lang an." }
